pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut it = txt.chars().rev();

    // Must be non-empty
    let last = match it.next() {
        Some(c) => c,
        None => return false,
    };

    // Last character must be an ASCII letter
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // Standalone: either single character, or previous char is a space
    match it.next() {
        None => true,
        Some(prev) => prev == ' ',
    }
}